import {
	Component,
	createContext,
	createEffect,
	createMemo,
	createSignal,
	on,
	onCleanup,
	onMount,
	ParentComponent,
	Setter,
	useContext,
} from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { cleanObject } from "#core/ui-next/utilities/game-core-utilities.js";

//#region Scene3d
class Scene3dContextProvider {
	constructor(public name: string) { }
}

const Scene3dContext = createContext<Scene3dContextProvider>();

export function useScene3dContext() {
	const context = useContext(Scene3dContext);

	if (!context) {
		throw new Error("No Scene3d context found!");
	}

	return context;
}

export interface Scene3dProps {
	name: string;
	ref?: (scene: WorldUI.Scene) => void;
}

export const Scene3dComponent: ParentComponent<Scene3dProps> = (props) => {
	// eslint-disable-next-line solid/reactivity
	const sceneContext = new Scene3dContextProvider(props.name);
	return <Scene3dContext.Provider value={sceneContext}>{props.children}</Scene3dContext.Provider>;
};

export const Scene3d = ComponentRegistry.register({
	name: "Scene3d",
	createInstance: Scene3dComponent,
});
//#endregion

//#region Camera3d
export interface Camera3dProps {
	cameraPos: float3;
	subjectPos: float3;
	fov?: number;
	up?: float3;
	clip?: float2;
	// Can nest children to create camera stack
	children?: () => Component<Camera3dProps>;
}

export const Camera3dComponent: Component<Camera3dProps> = (props) => {
	const cameraProps = createMemo(() => cleanObject({ fovy: props.fov, up: props.up, clip: props.clip }));

	onMount(() => {
		Camera.pushCamera(props.cameraPos, props.subjectPos, cameraProps());
	});

	onCleanup(() => {
		Camera.popCamera();
	});

	return null;
};

export const Camera3d = ComponentRegistry.register({
	name: "Camera3d",
	createInstance: Camera3dComponent,
});
//#endregion

//#region ModelGroup3d
class ModelGroup3dContextProvider {
	private _modelGroup: WorldUI.ModelGroup;

	public get modelGroup() {
		return this._modelGroup;
	}

	constructor(name: string) {
		this._modelGroup = WorldUI.createModelGroup(name);
	}

	dispose() {
		this._modelGroup.destroy();
	}
}

const ModelGroup3dContext = createContext<ModelGroup3dContextProvider>();

export function useModelGroup3dContext() {
	const context = useContext(ModelGroup3dContext);

	if (!context) {
		throw new Error("No ModelGroup3d context found!");
	}

	return context;
}

export interface ModelGroup3dProps {
	name: string;
	ref?: (scene: WorldUI.ModelGroup) => void;
}

const ModelGroup3dComponent: ParentComponent<ModelGroup3dProps> = (props) => {
	// eslint-disable-next-line solid/reactivity
	const groupContext = new ModelGroup3dContextProvider(props.name);

	createEffect(() => props.ref?.(groupContext.modelGroup));

	onCleanup(() => {
		groupContext.dispose();
	});

	return <ModelGroup3dContext.Provider value={groupContext}>{props.children}</ModelGroup3dContext.Provider>;
};

export const ModelGroup3d = ComponentRegistry.register({
	name: "ModelGroup3d",
	createInstance: ModelGroup3dComponent,
});
//#endregion

//#region Model3d
export interface Model3dProps {
	model: string;
	location?: WorldUI.Location;
	state?: string;
	hidden?: boolean;
	scale?: number;
	angle?: WorldUI.Angle;
	tintColor1?: WorldUI.Color;
	tintColor2?: WorldUI.Color;
	alpha?: number;
	seed?: number;
	placement?: PlacementMode;
	foreground?: boolean;
	needsShadows?: boolean;
	selectionScriptParams?: WorldUI.SelectionScriptParams;
	clearTemporalHistoryOnChange?: boolean;

	onTrigger?: (hash: number) => void;
	ref?: (model: WorldUI.ModelInstance | undefined) => void;
}

const defaultLocation: WorldUI.Location = {
	marker: WorldUI.createFixedMarker({ x: 0, y: 0, z: 0 }) ?? undefined,
	offset: { x: 0, y: 0, z: 0 },
};

const Model3dComponent: Component<Model3dProps> = (props) => {
	const modelGroupContext = useModelGroup3dContext();

	const [model, setModel] = createSignal<WorldUI.ModelInstance>();

	const modelParams = createMemo(() =>
		cleanObject({
			scale: props.scale,
			angle: props.angle,
			tintColor1: props.tintColor1,
			tintColor2: props.tintColor2,
			initialState: props.state,
			placement: props.placement,
			foreground: props.foreground,
			needsShadows: props.needsShadows,
			triggerCallbacks: !!props.onTrigger,
			selectionScriptParams: props.selectionScriptParams,
		}),
	);

	const callback = (id: number, hash: number) => {
		if (model()?.id == id) {
			props.onTrigger?.(hash);
		}
	}

	// eslint-disable-next-line solid/reactivity
	engine.on("ModelTrigger", callback);

	onCleanup(() => {
		engine.off("ModelTrigger", callback);
	});

	createEffect(
		on(
			() => props.hidden,
			(hidden, prevHidden) => {
				const alpha = hidden ? 0.0 : (props.alpha ?? 1);
				model()?.setAlpha(alpha);
				if (props.clearTemporalHistoryOnChange && prevHidden != hidden) {
					WorldUI.clearTemporalHistory();
				}
			},
		),
	);

	createEffect(() => props.ref?.(model()));

	createEffect(
		on(
			() => props.model,
			(modelName, prevModelName) => {
				model()?.setAssetName(modelName);
				if (props.clearTemporalHistoryOnChange && prevModelName != modelName) {
					WorldUI.clearTemporalHistory();
				}
			},
		),
	);

	createEffect(() => {
		if (props.state) {
			model()?.setState(props.state);
		}
	});

	createEffect(() => {
		model()?.updateSelectionScriptParams(modelParams());
	});

	onMount(() => {
		const model =
			modelGroupContext.modelGroup.addModel(props.model, props.location ?? defaultLocation, modelParams()) ??
			undefined;
		setModel(model);
	});

	return null;
};

export const Model3d = ComponentRegistry.register({
	name: "Model3d",
	createInstance: Model3dComponent,
});
//#endregion

//#region Background3d
class Background3dContextProvider {
	private setIsUpdatePending: Setter<boolean>;
	private layers: BackgroundLayer3dProps[] = [];

	public constructor() {
		const [isUpdatePending, setIsUpdatePending] = createSignal(true);
		this.setIsUpdatePending = setIsUpdatePending;

		createEffect(() => {
			if (isUpdatePending()) {
				this.rerender();
				this.setIsUpdatePending(false);
			}
		});
	}

	private cleanLayer(layer: BackgroundLayer3dProps) {
		return cleanObject({
			stretch: layer.stretch,
			alignX: layer.alignX,
			alignY: layer.alignY,
			alpha: layer.alpha,
			size: layer.size,
			sizeRel: layer.sizeRel,
			offset: layer.offset,
			offsetRel: layer.offsetRel,
			border_slice: layer.borderImageSlice,
			border_width: layer.borderImageWidth,
			flipX: layer.flipX,
			flipY: layer.flipY,
		}) as WorldUI.BackgroundParams;
	}

	private rerender() {
		WorldUI.clearBackground();
		const pass = UI.isInGame() ? BackgroundPass.UI : BackgroundPass.Game;
		for (const layer of this.layers) {
			if (layer.mask) {
				WorldUI.addMaskedBackgroundLayer(layer.texture, layer.mask, this.cleanLayer(layer), pass);
			} else {
				WorldUI.addBackgroundLayer(layer.texture, this.cleanLayer(layer), pass);
			}
		}
	}

	public addOrUpdateLayer(layer: BackgroundLayer3dProps) {
		const foundLayer = this.layers.find((l) => l.name == layer.name);
		if (foundLayer) {
			foundLayer.alignX = layer.alignX;
			foundLayer.alignY = layer.alignY;
			foundLayer.alpha = layer.alpha;
			foundLayer.borderImageSlice = layer.borderImageSlice;
			foundLayer.borderImageWidth = layer.borderImageWidth;
			foundLayer.mask = layer.mask;
			foundLayer.offset = layer.offset;
			foundLayer.offsetRel = layer.offsetRel;
			foundLayer.size = layer.size;
			foundLayer.sizeRel = layer.sizeRel;
			foundLayer.stretch = layer.stretch;
			foundLayer.texture = layer.texture;
			foundLayer.flipX = layer.flipX;
			foundLayer.flipY = layer.flipY;
		} else {
			this.layers.push({ ...layer });
		}

		this.setIsUpdatePending(true);
	}

	public removeLayer(layer: BackgroundLayer3dProps) {
		const foundLayerIndex = this.layers.findIndex((l) => l.name == layer.name);
		if (foundLayerIndex >= 0) {
			this.layers.splice(foundLayerIndex, 1);
		}
		this.setIsUpdatePending(true);
	}
}

const Background3dContext = createContext<Background3dContextProvider>();

function useBackground3dContext() {
	const context = useContext(Background3dContext);

	if (!context) {
		throw new Error("Unable to find Background3dContext to use");
	}

	return context;
}

const Background3dComponent: ParentComponent = (props) => {
	const context = new Background3dContextProvider();

	return <Background3dContext.Provider value={context}>{props.children}</Background3dContext.Provider>;
};

export const Background3d = ComponentRegistry.register({
	name: "Background3d",
	createInstance: Background3dComponent,
});

//#region BackgroundLayer3d
export interface BackgroundLayer3dProps {
	name: string;
	texture: string;
	mask?: string;
	stretch?: StretchMode;
	alignX?: AlignMode;
	alignY?: AlignMode;
	alpha?: number;
	size?: float2;
	sizeRel?: float2;
	offset?: float2;
	offsetRel?: float2;
	borderImageSlice?: string;
	borderImageWidth?: string;
	flipX?: boolean;
	flipY?: boolean;
}

const BackgroundLayer3dComponent: Component<BackgroundLayer3dProps> = (props) => {
	const context = useBackground3dContext();

	function setBackground() {
		context.addOrUpdateLayer(props);
	}

	createEffect(
		on(
			() => [props.texture, props.size, props.sizeRel, props.offset, props.offsetRel],
			() => setBackground(),
		),
	);

	onCleanup(() => {
		context.removeLayer(props);
	});

	return null;
};

export const BackgroundLayer3d = ComponentRegistry.register({
	name: "BackgroundLayer3d",
	createInstance: BackgroundLayer3dComponent,
});
//#endregion
